// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" использовать;
"src/models/product.hudhud" использовать;
"src/models/order.hudhud" использовать;

// Servisleri içe aktar
"src/services/auth.hudhud" использовать;
"src/services/payment.hudhud" использовать;
"src/services/notification.hudhud" использовать;

// Yardımcı классları içe aktar
"src/utils/validation.hudhud" использовать;
"src/utils/formatting.hudhud" использовать;

печать("============================================================");
печать("E-Ticaret Sistemi - Modüler Mimari Demo");
печать("============================================================\n");

// Servis örnekleri oluştur
пер authService = новый AuthService();
пер paymentService = новый PaymentService();
пер notificationService = новый NotificationService();

печать("1️⃣  KULLANICI KAYDI");
печать("─────────────────────────────────────────────────────────\n");

// Yeni использоватьıcı oluştur
пер newUser = новый User("Davut Süleyman", "davut@example.com", "güvenli123");
печать("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email истинаla
если (Validation.email(newUser.email)) {
    печать("✓ Email geçerli: " + newUser.email);
} иначе {
    печать("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
пер authResult = authService.register(newUser);
если (authResult.success) {
    печать("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

печать("\n2️⃣  ÜRÜN OLUŞTURMA");
печать("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
пер product = новый Product("MacBook Pro M3", 45000, 10, "Elektronik");
печать("Ürün oluşturuldu: " + product.bilgi());

// Fiyat истинаla
если (Validation.price(product.price)) {
    печать("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
если (product.inStock()) {
    печать("✓ Ürün stokta mevcut");
} иначе {
    печать("✗ Ürün stokta yok");
}

печать("\n3️⃣  SİPARİŞ OLUŞTURMA");
печать("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
пер order = новый Order(
    newUser.id,
    product.id,
    1,
    product.price
);
печать("Sipariş oluşturuldu: " + order.bilgi());

печать("\n4️⃣  ÖDEME İŞLEMİ");
печать("─────────────────────────────────────────────────────────\n");

// Ödeme işle
пер paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

если (paymentResult.success) {
    печать("✓ " + paymentResult.message);
    печать("  İşlem No: " + paymentResult.transactionId);
    печать("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    печать("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    печать("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} иначе {
    печать("✗ Ödeme başarısız: " + paymentResult.error);
}

печать("\n============================================================");
печать("✓ E-Ticaret sistemi demo tamamlandı!");
печать("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
печать("============================================================");

