// Order Model - Sipariş Modeli

класс Order {
    конструктор(userId, productId, quantity, totalPrice) {
        сам.id = Math.floor(Math.random() * 10000);
        сам.userId = userId;
        сам.productId = productId;
        сам.quantity = quantity;
        сам.totalPrice = totalPrice;
        сам.status = "pending";
        сам.createdAt = "2024-03-07";
    }

    функция bilgi() {
        вернуть "Sipariş #" + сам.id + " - Kullanıcı: " + сам.userId + ", Ürün: " + сам.productId + ", Adet: " + сам.quantity + ", Toplam: " + сам.totalPrice + " TL, Durum: " + сам.status;
    }

    функция confirm() {
        сам.status = "confirmed";
    }

    функция getId() {
        вернуть сам.id;
    }
}

