// Formatting Utilities - Formatlama Fonksiyonları

класс Formatting {
    статический функция currency(amount, currency) {
        если (currency == "TRY") {
            вернуть amount + " ₺";
        } иначе {
            если (currency == "USD") {
                вернуть "$" + amount;
            } иначе {
                если (currency == "EUR") {
                    вернуть "€" + amount;
                } иначе {
                    вернуть amount + " " + currency;
                }
            }
        }
    }

    статический функция date(date) {
        вернуть date;
    }

    статический функция phone(phone) {
        // (555) 123-4567 formatı
        вернуть "(" + phone + ")";
    }

    статический функция number(num) {
        // 1,234,567 formatı
        вернуть num;
    }
}

