// Validation Utilities - Doğrulama Fonksiyonları

класс Validation {
    статический функция email(email) {
        // Basit email истинаlama
        вернуть email.length > 5;
    }

    статический функция password(password) {
        // Şifre en az 6 karakter olmalı
        вернуть password.length >= 6;
    }

    статический функция price(price) {
        вернуть price > 0;
    }

    статический функция phone(phone) {
        // Telefon numarası истинаlama
        вернуть phone.length == 10;
    }

    статический функция required(value) {
        вернуть value.length > 0;
    }
}

